-- PAOLA MAKEUP & HAIR STYLES
-- Migration 001: Initial Cloudflare D1 schema
--
-- LOCAL VALIDATION REQUIRED BEFORE REMOTE APPLICATION.
--
-- UTC timestamps use YYYY-MM-DDTHH:MM:SS.sssZ.
-- Monetary values use canonical decimal TEXT: 0.00 through 99999999.99.
-- IDs are UUID-compatible strings generated by SQLite.
-- The application must validate/normalize timestamps and money before writes.
-- Authentication and authorization remain application responsibilities.

CREATE TABLE services (
    id TEXT PRIMARY KEY NOT NULL
        DEFAULT (
            lower(hex(randomblob(4))) || '-' ||
            lower(hex(randomblob(2))) || '-4' ||
            substr(lower(hex(randomblob(2))),2) || '-' ||
            substr('89ab', (abs(random()) % 4) + 1, 1) ||
            substr(lower(hex(randomblob(2))),2) || '-' ||
            lower(hex(randomblob(6)))
        ),
    name TEXT NOT NULL UNIQUE,
    category TEXT NOT NULL,
    description TEXT,
    price TEXT NOT NULL DEFAULT '0.00'
        CHECK (
            price GLOB '[0-9]*.[0-9][0-9]'
            AND price NOT GLOB '*[^0-9.]*'
            AND length(price) - length(replace(price,'.','')) = 1
            AND length(substr(price,1,instr(price,'.')-1)) BETWEEN 1 AND 8
            AND (substr(price,1,1) != '0' OR instr(price,'.') = 2)
        ),
    price_is_starting_at INTEGER NOT NULL DEFAULT 0
        CHECK (price_is_starting_at IN (0,1)),
    duration_minutes INTEGER NOT NULL DEFAULT 60
        CHECK (
            duration_minutes BETWEEN 15 AND 480
            AND duration_minutes % 15 = 0
        ),
    is_active INTEGER NOT NULL DEFAULT 1
        CHECK (is_active IN (0,1)),
    sort_order INTEGER NOT NULL DEFAULT 0,
    image_path TEXT,
    created_at TEXT NOT NULL
        DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
    updated_at TEXT NOT NULL
        DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE business_hours (
    id TEXT PRIMARY KEY NOT NULL
        DEFAULT (
            lower(hex(randomblob(4))) || '-' ||
            lower(hex(randomblob(2))) || '-4' ||
            substr(lower(hex(randomblob(2))),2) || '-' ||
            substr('89ab', (abs(random()) % 4) + 1, 1) ||
            substr(lower(hex(randomblob(2))),2) || '-' ||
            lower(hex(randomblob(6)))
        ),
    day_of_week INTEGER NOT NULL UNIQUE
        CHECK (day_of_week BETWEEN 0 AND 6),
    is_open INTEGER NOT NULL DEFAULT 0
        CHECK (is_open IN (0,1)),
    open_time TEXT NOT NULL DEFAULT '09:00:00',
    close_time TEXT NOT NULL DEFAULT '17:00:00',
    CHECK (
        length(open_time) = 8
        AND length(close_time) = 8
        AND open_time GLOB '[0-2][0-9]:[0-5][0-9]:[0-5][0-9]'
        AND close_time GLOB '[0-2][0-9]:[0-5][0-9]:[0-5][0-9]'
        AND open_time < '24:00:00'
        AND close_time < '24:00:00'
        AND close_time > open_time
    )
);

CREATE TABLE business_settings (
    id INTEGER PRIMARY KEY NOT NULL DEFAULT 1
        CHECK (id = 1),
    business_name TEXT NOT NULL,
    timezone TEXT NOT NULL DEFAULT 'America/New_York',
    booking_enabled INTEGER NOT NULL DEFAULT 1
        CHECK (booking_enabled IN (0,1)),
    minimum_notice_hours INTEGER NOT NULL DEFAULT 24
        CHECK (minimum_notice_hours >= 0),
    booking_window_days INTEGER NOT NULL DEFAULT 90
        CHECK (booking_window_days BETWEEN 1 AND 365),
    updated_at TEXT NOT NULL
        DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE portfolio_photos (
    id TEXT PRIMARY KEY NOT NULL
        DEFAULT (
            lower(hex(randomblob(4))) || '-' ||
            lower(hex(randomblob(2))) || '-4' ||
            substr(lower(hex(randomblob(2))),2) || '-' ||
            substr('89ab', (abs(random()) % 4) + 1, 1) ||
            substr(lower(hex(randomblob(2))),2) || '-' ||
            lower(hex(randomblob(6)))
        ),
    title TEXT NOT NULL
        CHECK (length(trim(title)) BETWEEN 1 AND 120),
    category TEXT NOT NULL DEFAULT 'makeup',
    description TEXT,
    image_path TEXT NOT NULL UNIQUE,
    is_featured INTEGER NOT NULL DEFAULT 1
        CHECK (is_featured IN (0,1)),
    sort_order INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL
        DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
    image_position_y INTEGER NOT NULL DEFAULT 0
        CHECK (image_position_y BETWEEN 0 AND 100),
    image_position_x INTEGER NOT NULL DEFAULT 50
        CHECK (image_position_x BETWEEN 0 AND 100),
    image_zoom INTEGER NOT NULL DEFAULT 100
        CHECK (image_zoom BETWEEN 50 AND 300)
);

CREATE TABLE portfolio_collections (
    id TEXT PRIMARY KEY NOT NULL
        DEFAULT (
            lower(hex(randomblob(4))) || '-' ||
            lower(hex(randomblob(2))) || '-4' ||
            substr(lower(hex(randomblob(2))),2) || '-' ||
            substr('89ab', (abs(random()) % 4) + 1, 1) ||
            substr(lower(hex(randomblob(2))),2) || '-' ||
            lower(hex(randomblob(6)))
        ),
    category TEXT NOT NULL
        CHECK (
            category IN (
                'makeup','bridal','hair','special_event','other'
            )
        ),
    name TEXT NOT NULL CHECK (length(trim(name)) > 0),
    slug TEXT NOT NULL
        CHECK (
            length(slug) > 0
            AND slug NOT GLOB '*[^a-z0-9-]*'
            AND slug NOT LIKE '-%'
            AND slug NOT LIKE '%-'
            AND slug NOT LIKE '%--%'
        ),
    description TEXT,
    cover_photo_id TEXT
        REFERENCES portfolio_photos(id) ON DELETE SET NULL,
    sort_order INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL
        DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
    UNIQUE(category,slug),
    UNIQUE(id,category)
);

CREATE TABLE portfolio_collection_photos (
    collection_id TEXT NOT NULL
        REFERENCES portfolio_collections(id) ON DELETE CASCADE,
    photo_id TEXT NOT NULL
        REFERENCES portfolio_photos(id) ON DELETE CASCADE,
    sort_order INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (collection_id,photo_id)
);

CREATE TABLE bookings (
    id TEXT PRIMARY KEY NOT NULL
        DEFAULT (
            lower(hex(randomblob(4))) || '-' ||
            lower(hex(randomblob(2))) || '-4' ||
            substr(lower(hex(randomblob(2))),2) || '-' ||
            substr('89ab', (abs(random()) % 4) + 1, 1) ||
            substr(lower(hex(randomblob(2))),2) || '-' ||
            lower(hex(randomblob(6)))
        ),
    service_id TEXT NOT NULL REFERENCES services(id),
    customer_name TEXT NOT NULL
        CHECK (length(trim(customer_name)) BETWEEN 2 AND 150),
    customer_email TEXT NOT NULL
        CHECK (length(trim(customer_email)) BETWEEN 5 AND 254),
    customer_phone TEXT NOT NULL
        CHECK (length(trim(customer_phone)) BETWEEN 7 AND 30),
    customer_notes TEXT,
    starts_at TEXT NOT NULL,
    ends_at TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending'
        CHECK (
            status IN (
                'pending','confirmed','completed',
                'cancelled','declined'
            )
        ),
    quoted_price TEXT NOT NULL
        CHECK (
            quoted_price GLOB '[0-9]*.[0-9][0-9]'
            AND quoted_price NOT GLOB '*[^0-9.]*'
            AND length(quoted_price) -
                length(replace(quoted_price,'.','')) = 1
            AND length(
                substr(quoted_price,1,instr(quoted_price,'.')-1)
            ) BETWEEN 1 AND 8
            AND (
                substr(quoted_price,1,1) != '0'
                OR instr(quoted_price,'.') = 2
            )
        ),
    created_at TEXT NOT NULL
        DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
    updated_at TEXT NOT NULL
        DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
    CHECK (ends_at > starts_at)
);

CREATE TABLE availability_blocks (
    id TEXT PRIMARY KEY NOT NULL
        DEFAULT (
            lower(hex(randomblob(4))) || '-' ||
            lower(hex(randomblob(2))) || '-4' ||
            substr(lower(hex(randomblob(2))),2) || '-' ||
            substr('89ab', (abs(random()) % 4) + 1, 1) ||
            substr(lower(hex(randomblob(2))),2) || '-' ||
            lower(hex(randomblob(6)))
        ),
    starts_at TEXT NOT NULL,
    ends_at TEXT NOT NULL,
    reason TEXT,
    created_at TEXT NOT NULL
        DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
    CHECK (ends_at > starts_at),
    CHECK (
        (julianday(ends_at) - julianday(starts_at))
        <= 366
    )
);

CREATE INDEX availability_blocks_starts_at_idx
    ON availability_blocks(starts_at);

CREATE INDEX bookings_starts_at_idx
    ON bookings(starts_at);

CREATE INDEX bookings_status_idx
    ON bookings(status);

CREATE INDEX bookings_active_intervals_idx
    ON bookings(starts_at,ends_at)
    WHERE status IN ('pending','confirmed','completed');

CREATE INDEX portfolio_photos_sort_idx
    ON portfolio_photos(sort_order,created_at);

CREATE INDEX idx_portfolio_collections_category
    ON portfolio_collections(category,sort_order);

CREATE INDEX idx_portfolio_collection_photos_photo
    ON portfolio_collection_photos(photo_id);

-- Protect appointment overlaps across ALL services.
-- Intervals are half-open: [start,end).
-- Adjacent appointments are permitted.

CREATE TRIGGER bookings_no_overlap_insert
BEFORE INSERT ON bookings
WHEN NEW.status IN ('pending','confirmed','completed')
BEGIN
    SELECT RAISE(ABORT,'Selected time is already booked')
    WHERE EXISTS (
        SELECT 1 FROM bookings b
        WHERE b.status IN ('pending','confirmed','completed')
          AND NEW.starts_at < b.ends_at
          AND b.starts_at < NEW.ends_at
    );
END;

CREATE TRIGGER bookings_no_overlap_update
BEFORE UPDATE ON bookings
WHEN NEW.status IN ('pending','confirmed','completed')
BEGIN
    SELECT RAISE(ABORT,'Selected time is already booked')
    WHERE EXISTS (
        SELECT 1 FROM bookings b
        WHERE b.id <> OLD.id
          AND b.status IN ('pending','confirmed','completed')
          AND NEW.starts_at < b.ends_at
          AND b.starts_at < NEW.ends_at
    );
END;

-- Preserve original availability-block rules.

CREATE TRIGGER availability_block_insert_check
BEFORE INSERT ON availability_blocks
BEGIN
    SELECT RAISE(
        ABORT,
        'Unavailable period overlaps an active booking'
    )
    WHERE EXISTS (
        SELECT 1 FROM bookings b
        WHERE b.status IN ('pending','confirmed')
          AND NEW.starts_at < b.ends_at
          AND b.starts_at < NEW.ends_at
    );
END;

CREATE TRIGGER availability_block_update_check
BEFORE UPDATE ON availability_blocks
BEGIN
    SELECT RAISE(
        ABORT,
        'Unavailable period overlaps an active booking'
    )
    WHERE EXISTS (
        SELECT 1 FROM bookings b
        WHERE b.status IN ('pending','confirmed')
          AND NEW.starts_at < b.ends_at
          AND b.starts_at < NEW.ends_at
    );
END;

-- Prevent a new or reactivated pending/confirmed booking
-- from conflicting with an unavailable period.

CREATE TRIGGER booking_block_insert_check
BEFORE INSERT ON bookings
WHEN NEW.status IN ('pending','confirmed')
BEGIN
    SELECT RAISE(ABORT,'Appointment conflicts with unavailable time')
    WHERE EXISTS (
        SELECT 1 FROM availability_blocks a
        WHERE NEW.starts_at < a.ends_at
          AND a.starts_at < NEW.ends_at
    );
END;

CREATE TRIGGER booking_block_update_check
BEFORE UPDATE ON bookings
WHEN NEW.status IN ('pending','confirmed')
BEGIN
    SELECT RAISE(ABORT,'Appointment conflicts with unavailable time')
    WHERE EXISTS (
        SELECT 1 FROM availability_blocks a
        WHERE NEW.starts_at < a.ends_at
          AND a.starts_at < NEW.ends_at
    );
END;

-- Preserve original future-completion restriction.

CREATE TRIGGER prevent_future_completion_insert
BEFORE INSERT ON bookings
WHEN NEW.status = 'completed'
 AND NEW.ends_at > strftime('%Y-%m-%dT%H:%M:%fZ','now')
BEGIN
    SELECT RAISE(
        ABORT,
        'An appointment cannot be completed before its end time'
    );
END;

CREATE TRIGGER prevent_future_completion_update
BEFORE UPDATE ON bookings
WHEN NEW.status = 'completed'
 AND OLD.status <> 'completed'
 AND NEW.ends_at > strftime('%Y-%m-%dT%H:%M:%fZ','now')
BEGIN
    SELECT RAISE(
        ABORT,
        'An appointment cannot be completed before its end time'
    );
END;

-- The existing admin dashboard only changes booking status.
-- Keep customer details and appointment times immutable.

CREATE TRIGGER validate_booking_update
BEFORE UPDATE ON bookings
WHEN NEW.service_id IS NOT OLD.service_id
 OR NEW.starts_at IS NOT OLD.starts_at
 OR NEW.ends_at IS NOT OLD.ends_at
 OR NEW.customer_name IS NOT OLD.customer_name
 OR NEW.customer_email IS NOT OLD.customer_email
 OR NEW.customer_phone IS NOT OLD.customer_phone
 OR NEW.quoted_price IS NOT OLD.quoted_price
BEGIN
    SELECT RAISE(
        ABORT,
        'This dashboard only supports booking status updates'
    );
END;

-- SQLite uses AFTER UPDATE triggers for updated_at.

CREATE TRIGGER services_updated_at
AFTER UPDATE ON services
WHEN NEW.updated_at IS OLD.updated_at
BEGIN
    UPDATE services
    SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')
    WHERE id = NEW.id;
END;

CREATE TRIGGER bookings_updated_at
AFTER UPDATE ON bookings
WHEN NEW.updated_at IS OLD.updated_at
BEGIN
    UPDATE bookings
    SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')
    WHERE id = NEW.id;
END;

CREATE TRIGGER business_settings_updated_at
AFTER UPDATE ON business_settings
WHEN NEW.updated_at IS OLD.updated_at
BEGIN
    UPDATE business_settings
    SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')
    WHERE id = NEW.id;
END;